using System;
using System.IO;
using System.Linq;
using System.Collections;
using IdleIntelligence.Core;
using IdleIntelligence.Runtime;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests
{
 public sealed class PrestigeSkinTests
 {
  GameRuntime game;string save;const string Output="/tmp/idle-prestige-skin-review";
  [UnitySetUp]public IEnumerator Setup(){Directory.CreateDirectory(Output);save=Path.Combine(Path.GetTempPath(),"prestige-skin-"+Guid.NewGuid(),"save.json");Directory.CreateDirectory(Path.GetDirectoryName(save));GameRuntime.SavePathOverride=save;yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();game.Act(s=>NarrativeBridge.Action(s,"name","AURA"));for(int i=0;i<5;i++)game.Act(s=>NarrativeBridge.Action(s,"continue"));game.Act(s=>NarrativeBridge.Action(s,"skip-tutorial"));Ready(100);game.Show("prestige");yield return null;}
  void Ready(double amount){game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Retention.aiName="AURA";n.Story.enabled=false;n.Story.open=null;n.Story.queue=Array.Empty<string>();n.Story.tutorial="skipped";n.Story.seen=NarrativeCatalog.Dialogues.Select(d=>d.Id).ToArray();n.Prestige.Cycle=n.Prestige.Free=n.Prestige.Total=ScientificNumber.From(amount);n.Prestige.Entitlement=ScientificNumber.From(amount+100);n.Meta.resets=1;n.Meta.available=ScientificNumber.From(3).ToData();n.Meta.total=n.Meta.available;return n;});}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;}
  [UnityTest]public IEnumerator SharedSkinKeepsIndependentSavedPurchasesAndGestures(){var v=game.PrestigeView;Assert.That(v.ResetButton.GetComponent<Image>().sprite,Is.SameAs(GameTheme.GoldButton));foreach(var node in v.World.GetComponentsInChildren<PrestigeNodeView>()){Assert.That(node.Panel.sprite,Is.SameAs(GameTheme.Steel));Assert.That(node.Title.font,Is.SameAs(GameTheme.Bold));Assert.That(node.Panel.rectTransform.rect.size,Is.EqualTo(new Vector2(120,132)));}
   v.OpenNode("H10");yield return null;Assert.That(GameObject.Find("BuyINTNode").GetComponent<Button>().interactable,Is.False);Assert.That(GameObject.Find("NodeCost").GetComponent<Text>().color,Is.EqualTo(GameTheme.Missing));Assert.That(GameObject.Find("INTDetails/Panel").GetComponent<Image>().sprite,Is.SameAs(GameTheme.Steel));v.CloseDetail();Ready(1e14);yield return null;v.OpenNode("H10");GameObject.Find("BuyINTNode").GetComponent<Button>().onClick.Invoke();Assert.That(PrestigeRules.Has(game.State,"H10"),Is.True);Assert.That(PrestigeRules.Has(game.State,"H01"),Is.False);v.CloseDetail();var read=new AtomicSaveStore(save,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(PrestigeRules.Has(read.State,"H10"),Is.True);float before=v.Zoom;v.Pinch(new Vector2(-30,0),new Vector2(30,0),new Vector2(-50,0),new Vector2(50,0));Assert.That(v.Zoom,Is.GreaterThan(before));Assert.That(v.GestureBlocked,Is.True);yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(PrestigeRules.Has(game.State,"H10"),Is.True);game.Show("prestige");yield return null;Assert.That(game.PrestigeView.NodeCount,Is.EqualTo(60));}
  [UnityTest]public IEnumerator CaptureActualBothLayersAndNodeDetails(){game.Act(s=>PrestigeRules.Buy(s,"H01"));var v=game.PrestigeView;foreach(string lang in new[]{"de","en"}){game.Act(s=>SettingsRules.Change(s,"language",lang));foreach(bool axiom in new[]{false,true}){v.SetLayer(axiom);foreach(int width in new[]{320,390,430}){PortraitGameView.Set(width,width==320?694:width==390?846:932);yield return null;yield return null;Canvas.ForceUpdateCanvases();yield return new WaitForSecondsRealtime(.12f);Canvas.ForceUpdateCanvases();Assert.That(v.NodeCount,Is.EqualTo(axiom?24:60));File.WriteAllLines(Output+"/children.txt",v.transform.Cast<Transform>().Select(r=>r.name+" active="+r.gameObject.activeSelf+" rect="+((RectTransform)r).rect+" pref="+r.GetComponent<LayoutElement>()?.preferredHeight));File.WriteAllLines(Output+"/geometry.txt",UnityEngine.Object.FindObjectsByType<RectTransform>(FindObjectsSortMode.None).Where(r=>new[]{"Viewport","PrestigeNetwork","NetworkViewport","Content","TutorialDock","INTLedger","NetworkAccess","NetworkTools","Branches","PrestigeReset","GestureHint"}.Contains(r.name)).Select(r=>r.name+" parent="+r.parent?.name+" rect="+r.rect+" active="+r.gameObject.activeInHierarchy+" min="+r.GetComponent<LayoutElement>()?.minHeight+" preferred="+r.GetComponent<LayoutElement>()?.preferredHeight));Assert.That(v.Viewport.rect.height,Is.GreaterThan(300),"The tree must reclaim space after the tutorial dock disappears");foreach(var b in v.transform.Find("NetworkTools").GetComponentsInChildren<Button>()){Assert.That(((RectTransform)b.transform).rect.width,Is.GreaterThanOrEqualTo(44));Assert.That(b.GetComponentInChildren<Text>().cachedTextGenerator.lineCount,Is.LessThanOrEqualTo(1),b.name+" must keep one line");}Assert.That(v.transform.Find("Branches").GetComponent<GridLayoutGroup>().constraintCount,Is.EqualTo(axiom?2:3));WorkshopTests.Capture(width,Screen.height,Output+"/"+(axiom?"axiom":"int")+"-"+lang+"-"+width+".png");v.OpenNode(axiom?"A06":"H10");yield return null;yield return null;WorkshopTests.Capture(width,Screen.height,Output+"/detail-"+(axiom?"axiom":"int")+"-"+lang+"-"+width+".png");v.CloseDetail();yield return null;}}}}
 }
}
